"""AI-connection UI composition with an isolated metadata editor runtime."""
from __future__ import annotations

from .web_ai_connection_editor_runtime import AI_CONNECTION_EDITOR_SCRIPT
from .web_ai_connection_delete_runtime import AI_CONNECTION_DELETE_SCRIPT

AI_CONNECTION_RENDER_SCRIPT = 'function renderAiClients(){if(!state.aiClients.length){aiClientTable.innerHTML=\'<div class="empty">No OAuth clients registered yet.</div>\';return}aiClientTable.innerHTML=\'<table class="table"><thead><tr><th>Name</th><th>Note</th><th>Registered</th><th></th></tr></thead><tbody>\'+state.aiClients.map(c=>`<tr><td><b>${esc(c.display_name||c.client_name||\'MCP Client\')}</b><div class="muted path">${esc(c.client_id)}</div></td><td>${esc(c.note||\'—\')}</td><td>${esc(timefmt(c.created_at))}</td><td><div class="toolbar" style="margin:0;justify-content:flex-end"><button class="btn secondary" onclick="editAiConnection(\'${encodeURIComponent(c.client_id)}\')">Edit</button><button class="btn danger"${aiConnectionDeleteButtonState(c.client_id)} onclick="deleteAiConnection(\'${encodeURIComponent(c.client_id)}\')">Delete</button></div></td></tr>`).join(\'\')+\'</tbody></table>\'}\n'

AI_CONNECTION_ACTION_SCRIPT = ("async function copyMcpUrl(){const u='https://lucasmcp.com/mcp';mcpUrl.value=u;try{await navigator.clipboard.writeText(u);toast('MCP URL copied')}catch{mcpUrl.select();document.execCommand('copy');toast('MCP URL copied')}}\nfunction openAiModal(){if(state.billing&&state.aiClients.length>=state.billing.ai_account_limit){toast('AI account limit reached. Remove an unused AI connection.');setTimeout(()=>location.href='/billing',500);return}aiModal.classList.remove('hidden');aiModalUrl.value='https://lucasmcp.com/mcp';aiClientType.value='';updateAiHelp();setTimeout(()=>aiClientType.focus(),50)}\nfunction updateAiHelp(){const raw=aiClientType.value.trim(),n=raw.toLowerCase();const tips={chatgpt:'Create a custom MCP app, use the Lucas MCP URL, choose OAuth, then scan tools.',claude:'Add Lucas as a remote MCP connector and use OAuth when prompted.',gemini:'Add Lucas through an MCP-compatible integration and authorize with Lucas OAuth.',cursor:'Add a remote MCP server using the Lucas MCP URL and complete OAuth authorization.',codex:'Configure Lucas as a remote MCP server using the URL shown above.','claude code':'Configure Lucas as a remote MCP server using the URL shown above.'};aiHelp.textContent=!raw?'Enter a name for the AI assistant you want to connect with Lucas.':(tips[n]||`Add the Lucas MCP URL to ${raw} and complete OAuth authorization.`)}\n"
    + AI_CONNECTION_EDITOR_SCRIPT
    + AI_CONNECTION_DELETE_SCRIPT)
